local opt = vim.opt

opt.number = true
opt.relativenumber = true
opt.signcolumn = "yes"
opt.cursorline = true
opt.termguicolors = true
opt.mouse = "a"

opt.expandtab = true
opt.shiftwidth = 2
opt.tabstop = 2
opt.smartindent = true

opt.ignorecase = true
opt.smartcase = true

opt.splitright = true
opt.splitbelow = true

opt.wrap = false
opt.scrolloff = 8
opt.sidescrolloff = 8

opt.undofile = true
opt.swapfile = false
opt.updatetime = 250

opt.clipboard = "unnamedplus"

opt.completeopt = { "menu", "menuone", "noselect" }
